"""Harvest ready plots through a configured HTTP interface."""
import argparse
import json
import sys
from urllib.request import Request, urlopen


def request(base_url, path, body=None):
    data = None if body is None else json.dumps(body).encode()
    headers = {"Content-Type": "application/json"}
    with urlopen(Request(base_url.rstrip("/") + path, data=data, headers=headers), timeout=3) as response:
        return json.load(response)


def harvest_ready(base_url):
    snapshot = request(base_url, "/plots")
    harvested = []
    for plot in snapshot["plots"]:
        if plot["state"] != "ready":
            continue
        result = request(base_url, "/harvest", {"plot_id": plot["id"], "idempotency_key": "harvest:" + plot["id"]})
        if result.get("harvested") is not True:
            raise ValueError("Harvest was not confirmed")
        harvested.append(plot["id"])
    return {"harvested": harvested}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--base-url", required=True)
    args = parser.parse_args()
    try:
        print(json.dumps(harvest_ready(args.base_url)))
    except Exception as error:
        print(json.dumps({"error": str(error)}), file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
